<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/Upload.php';Auth::requireRole('admin');$pageTitle='مدیریت اسلایدر';$edit=null;
if(isset($_GET['delete'])&&Auth::verifyCsrf($_GET['csrf_token']??'')){Database::execute('DELETE FROM carousel_items WHERE id=?',[(int)$_GET['delete']]);flash('آیتم حذف شد.');redirect('/admin/carousel.php');}
if(isset($_GET['edit']))$edit=Database::fetch('SELECT * FROM carousel_items WHERE id=?',[(int)$_GET['edit']]);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/carousel.php');}$image=$_POST['current_image']??'';if(!empty($_FILES['image']['name'])){$up=Upload::save($_FILES['image'],'uploads/carousel',Upload::IMAGE_EXTENSIONS);if(!$up['ok']){flash($up['error'],'danger');redirect('/admin/carousel.php');}$image=$up['file_path'];}$id=(int)($_POST['id']??0);$data=[$_POST['title'],$_POST['description'],$image,$_POST['button_text'],$_POST['button_link'],(int)$_POST['sort_order'],$_POST['status']];if($id){Database::execute('UPDATE carousel_items SET title=?,description=?,image_path=?,button_text=?,button_link=?,sort_order=?,status=?,updated_at=NOW() WHERE id=?',[...$data,$id]);flash('آیتم بروزرسانی شد.');}else{Database::execute('INSERT INTO carousel_items (title,description,image_path,button_text,button_link,sort_order,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,NOW(),NOW())',$data);flash('آیتم ایجاد شد.');}redirect('/admin/carousel.php');}
$items=Database::fetchAll('SELECT * FROM carousel_items ORDER BY sort_order ASC,id DESC');require __DIR__.'/../views/partials/admin-header.php';?>
<form class="card admin-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><input type="hidden" name="current_image" value="<?=e($edit['image_path']??'')?>"><div class="grid grid-2"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($edit['title']??'')?>" required></label><label class="form-field"><span>تصویر</span><input type="file" name="image" accept="image/png,image/jpeg"><?php if(!empty($edit['image_path'])):?><small><?=e($edit['image_path'])?></small><?php endif;?></label><label class="form-field"><span>متن دکمه</span><input name="button_text" value="<?=e($edit['button_text']??'') ?>"></label><label class="form-field"><span>لینک دکمه</span><input name="button_link" value="<?=e($edit['button_link']??'') ?>"></label><label class="form-field"><span>ترتیب</span><input type="number" name="sort_order" value="<?=e($edit['sort_order']??'0')?>"></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="active" <?=($edit['status']??'')==='active'?'selected':''?>>active</option><option value="disabled" <?=($edit['status']??'')==='disabled'?'selected':''?>>disabled</option></select></label><label class="form-field"><span>توضیحات</span><textarea name="description"><?=e($edit['description']??'')?></textarea></label></div><button class="btn btn-primary">ذخیره</button><a class="btn" href="/admin/carousel.php">جدید</a></form>
<div class="table-wrap"><table><thead><tr><th>عنوان</th><th>ترتیب</th><th>وضعیت</th><th>تصویر</th><th>عملیات</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['title'])?></td><td><?=e($i['sort_order'])?></td><td><?=e($i['status'])?></td><td><?=e($i['image_path'])?></td><td class="actions"><a class="btn btn-small" href="?edit=<?=$i['id']?>">ویرایش</a><a class="btn btn-small btn-danger" onclick="return confirm('حذف شود؟')" href="?delete=<?=$i['id']?>&csrf_token=<?=e(Auth::csrfToken())?>">حذف</a></td></tr><?php endforeach;?></tbody></table></div></section></main></div><script src="/assets/js/app.js"></script></body></html>
